  const pal=[[5,12,48],[8,32,78],[12,62,108],[18,98,128],[28,138,138],[65,165,125],[120,185,95],[175,195,72],[215,190,58],[225,158,55],[205,115,62],[172,68,58],[118,32,52],[62,16,46],[28,10,40],[5,12,48]];
